<script setup>
import {ref,onMounted,onBeforeUnmount,computed} from 'vue'
import {adminFetch,auth} from './adminApi.js'
const props=defineProps({kind:String})
const items=ref([]),detail=ref(null),error=ref(''),busy=ref(false),all=ref(true),offset=ref(0),next=ref(null),date=ref(''),note=ref('')
const approve=['owner','admin'].includes(auth.user?.role)
const zone=Intl.DateTimeFormat().resolvedOptions().timeZone
const state={review:'На согласовании',scheduled:'Запланировано',published:'Опубликовано',rejected:'Возвращено с замечаниями',cancelled:'Отменено',stale:'Устарело',failed:'Ошибка публикации'}
const fields={title:'Заголовок',slug:'Адрес',content:'Текст',sections:'Блоки',seo:'SEO',excerpt:'Описание',category:'Рубрика',tags:'Теги',cover_url:'Обложка',published:'Публикация'}
const changes=computed(()=>detail.value?Object.keys(fields).filter(k=>JSON.stringify(detail.value.payload[k])!==JSON.stringify(detail.value.current?.[k])):[])
const show=v=>v===undefined?'—':typeof v==='string'?v:JSON.stringify(v,null,2)
const local=iso=>{if(!iso)return '';const d=new Date(iso);return new Date(+d-d.getTimezoneOffset()*60000).toISOString().slice(0,16)}
const format=iso=>iso?new Date(iso).toLocaleString('ru'):'—'
async function request(path,method='GET',body){const r=await adminFetch('/api/admin/'+props.kind+'/publications'+path,{method,signal:AbortSignal.timeout(15000),...(body?{headers:{'content-type':'application/json'},body:JSON.stringify(body)}:{})});const data=await r.json();if(!r.ok)throw Error(data.error||'Ошибка запроса');return data}
async function reload(){try{const r=await request('?state='+(all.value?'all':'active')+'&offset='+offset.value);items.value=r.items;next.value=r.next_offset}catch(e){error.value=e.message}}
async function changeFilter(){offset.value=0;await reload()}
async function inspect(row){error.value='';try{detail.value=await request('/'+row.id);date.value=Date.parse(detail.value.requested_at)>Date.now()+5000?local(detail.value.requested_at):'';note.value=''}catch(e){error.value=e.message}}
async function decide(action){if(busy.value||!detail.value)return;if(action==='approve'&&!confirm(date.value?'Одобрить именно этот текст и назначить публикацию на выбранное время?':'Опубликовать именно этот текст сейчас?'))return;if(action==='cancel'&&!confirm('Отменить ожидающую заявку?'))return;busy.value=true;error.value='';try{const r=await request('/'+detail.value.id+'/'+action,'POST',{revision:detail.value.revision,note:note.value,publish_at:date.value?new Date(date.value).toISOString():null});await inspect(r);await reload()}catch(e){error.value=e.message;await reload()}finally{busy.value=false}}
let timer
onMounted(()=>{reload();timer=setInterval(reload,30000)})
onBeforeUnmount(()=>clearInterval(timer))
defineExpose({reload})
</script>
<template>
 <section class="panel publication-queue" aria-label="Очередь публикаций"><div class="panel-heading"><h2>Согласование и публикации</h2><button class="row-btn" @click="reload">Обновить очередь</button></div><label class="queue-filter"><input type="checkbox" v-model="all" @change="changeFilter"> Показывать завершённые заявки</label><p class="queue-help">{{approve?'Здесь можно проверить отправленный текст, вернуть его с комментарием или одобрить публикацию.':'Здесь ваши заявки и замечания администратора. Изменения опубликованных материалов отправляйте на согласование из редактора.'}}</p><p v-if="error&&!detail" class="alert" role="alert">{{error}}</p><div class="table-scroll"><table><thead><tr><th>Материал</th><th>Состояние</th><th>Время публикации</th><th></th></tr></thead><tbody><tr v-for="row in items" :key="row.id"><td>{{row.title}}</td><td>{{state[row.state]}}</td><td>{{format(row.scheduled_at||row.requested_at)}}</td><td><button class="row-btn" @click="inspect(row)">Проверить заявку</button></td></tr></tbody></table><p v-if="!items.length" class="empty">Заявок пока нет.</p></div><div class="queue-pagination"><button v-if="offset" class="row-btn" @click="offset=Math.max(0,offset-20);reload()">Предыдущие заявки</button><button v-if="next!==null" class="row-btn" @click="offset=next;reload()">Следующие заявки</button></div>
 <div v-if="detail" class="modal-backdrop"><div class="modal publication-detail" role="dialog" aria-label="Проверка публикации"><div class="modal-heading"><h2>{{detail.payload.title}}</h2><button :disabled="busy" aria-label="Закрыть проверку публикации" @click="detail=null">×</button></div><p><strong>{{state[detail.state]}}</strong> · Исходная версия {{detail.base_revision}}</p><p v-if="detail.note" class="decision-note">Комментарий: {{detail.note}}</p><p v-if="detail.failure" class="alert">{{detail.failure}}</p><p v-if="['review','scheduled','stale'].includes(detail.state)&&(!detail.current||detail.current.deleted_at||String(detail.current.revision)!==detail.base_revision)" class="queue-help">Исходный материал изменён или удалён. Ожидающую заявку необходимо отправить заново с актуальной версией.</p><details v-for="field in changes" :key="field" class="publication-diff"><summary>{{fields[field]}}</summary><div class="diff-columns"><div><strong>Сейчас на сервере</strong><pre>{{show(detail.current?.[field])}}</pre></div><div><strong>Отправлено на публикацию</strong><pre>{{show(detail.payload[field])}}</pre></div></div></details><details><summary>Полный отправленный текст</summary><pre>{{show(detail.payload)}}</pre></details><p v-if="error" class="alert" role="alert">{{error}}</p><fieldset :disabled="busy"><template v-if="approve&&detail.state==='review'"><label>Время одобренной публикации ({{zone}})<input v-model="date" type="datetime-local"><small>Оставьте пустым для публикации сразу после одобрения.</small></label><label>Комментарий к решению<textarea v-model="note" maxlength="2000" rows="3"></textarea></label><button class="primary-btn" @click="decide('approve')">{{date?'Одобрить и запланировать':'Одобрить и опубликовать'}}</button><button class="row-btn" :disabled="!note.trim()" @click="decide('reject')">Вернуть с комментарием</button></template><button v-if="['review','scheduled'].includes(detail.state)" class="row-btn danger" @click="decide('cancel')">Отменить заявку</button></fieldset></div></div>
 </section>
</template>
<style scoped>
.publication-queue{margin-top:25px}.queue-filter,.queue-help,.queue-pagination{margin:14px 20px}.queue-filter{display:flex;gap:8px;font-size:12px}.queue-help{font-size:12px;line-height:1.6;color:#62776c}.publication-detail{width:min(1000px,100%);overflow-wrap:anywhere}.publication-detail fieldset{border:0;padding:0;display:flex;flex-wrap:wrap;gap:12px;margin-top:20px;min-width:0}.publication-detail label{width:100%}.publication-diff{margin:14px 0}summary{cursor:pointer;font-weight:700}.diff-columns{display:grid;grid-template-columns:1fr 1fr;gap:15px}.diff-columns>div{min-width:0}pre{max-height:320px;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px;background:#f6f8fa;padding:12px}.decision-note{background:#fff8e2;padding:14px;white-space:pre-wrap}.publication-detail small{font-weight:400}.publication-detail p{line-height:1.6}@media(max-width:600px){.diff-columns{grid-template-columns:1fr}}
</style>
